import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import extractText from 'flarum/common/utils/extractText';
const t = (key, params = {}) => app.translator.trans(`ernestdefoe-hearth.admin.colors.${key}`, params);
const HEX = /^#[0-9a-fA-F]{6}$/;

/**
 * One of Hearth's four colours: named presets as swatches, a colour picker,
 * and the hex for anyone who has a colour in mind. All three write the same
 * setting; the server checks it again (src/Palette.php) before it reaches
 * the page.
 */
export default class ColorRow extends Component {
  view() {
    const {
      name,
      label,
      help,
      presets,
      fallback,
      stream
    } = this.attrs;
    const raw = String(stream() || '');
    const current = HEX.test(raw) ? raw.toUpperCase() : fallback;
    const id = 'hearth-color-' + name;
    // Translations come back as vnodes; attributes need plain text.
    const text = extractText(label);
    return m("div", {
      className: "Form-group HearthColorRow"
    }, m("label", {
      htmlFor: id
    }, label), m("div", {
      className: "helpText"
    }, help), m("div", {
      className: "HearthColorRow-controls"
    }, m("div", {
      className: "HearthColorRow-swatches",
      role: "group",
      "aria-label": extractText(t('presets_label', {
        label: text
      }))
    }, presets.map(preset => {
      const on = preset.hex.toUpperCase() === current;
      const presetName = extractText(t('presets.' + preset.name));
      return m("button", {
        type: "button",
        className: 'HearthColorRow-swatch' + (on ? ' is-on' : ''),
        "aria-pressed": on ? 'true' : 'false',
        title: presetName + ' ' + preset.hex,
        onclick: () => stream(preset.hex)
      }, m("span", {
        className: "HearthColorRow-chip",
        style: {
          background: preset.hex
        },
        "aria-hidden": "true"
      }), m("span", {
        className: "HearthColorRow-name"
      }, presetName));
    })), m("input", {
      id: id,
      type: "color",
      className: "HearthColorRow-picker",
      value: current.toLowerCase(),
      "aria-label": extractText(t('custom_label', {
        label: text
      })),
      oninput: e => stream((e.target.value || '').toUpperCase())
    }), m("input", {
      type: "text",
      className: "FormControl HearthColorRow-hex",
      value: raw,
      maxlength: 7,
      spellcheck: false,
      "aria-label": extractText(t('hex_label', {
        label: text
      })),
      placeholder: fallback,
      oninput: e => stream(e.target.value.trim())
    })), raw && !HEX.test(raw) ? m("div", {
      className: "HearthColorRow-error"
    }, t('invalid', {
      fallback
    })) : null);
  }
}